-- | Hand-built Net definitions and documents, against the reference.
--
-- @differential/hand_built_corpus.json@ is generated by
-- @differential/hand_built_corpus.py@ from the pinned Python reference. A
-- Haskell record built with its constructor is the reference's
-- @Model.model_construct(...)@, and an @mk*@ function is the reference's
-- validating @Model(...)@ call. Each case is one of:
--
-- * @construct@: a validating constructor with typed arguments, and the
--   reference's @ValidationError@ text (or success);
-- * @definition@: an edited definition built without validation, and the
--   reference's @compile_net_definition@ and @serialize_net_definition@
--   verdicts;
-- * @serialize-document@: an edited document built without validation, and
--   the reference's @serialize_net_document@ verdict;
-- * @project-document@: @project_net_document@ of the corpus's net with
--   edited positions and an unvalidated lineage;
-- * @parse-document@: @parse_net_document@ of a document with deep token
--   data or metadata, then @serialize_net_document@ of the result.
--
-- A successful serialization is pinned by the SHA-256 of its bytes.
module Petrus.Impetus.HandBuiltCorpusSpec (spec) where

import Control.Monad (forM_)
import Crypto.Hash.SHA256 qualified as SHA256
import Data.ByteString (ByteString)
import Data.ByteString qualified as BS
import Data.Text (Text)
import Data.Text qualified as T
import Numeric (showHex)
import Petrus.Activity.Number (Number (..))
import Petrus.Impetus.NetDefinition
import Petrus.Impetus.NetDefinitionCorpusSpec (findPackageFile)
import Petrus.Impetus.NetDocument
import Petrus.Impetus.Petrinet.Schema (ArcMode (..), Net)
import Petrus.Json
import Test.Hspec

-- | A recorded outcome: success (with the serialization's digest, when
-- there is one) or the exact refusal.
data Outcome = Ok | Digest Text | Refused Text
  deriving stock (Eq, Show)

data Corpus = Corpus
  { definitionBase :: Json
  , documentBase :: Json
  , projectionBase :: Json
  , cases :: [Json]
  }

spec :: Spec
spec = describe "hand-built Net definitions and documents (differential corpus)" $ do
  path <- runIO (findPackageFile ["differential/hand_built_corpus.json", "packages/petrus-impetus/differential/hand_built_corpus.json"])
  corpus <- runIO (BS.readFile path >>= either fail pure . loadCorpus)
  net <- runIO (either (fail . T.unpack) pure (compileNetDefinition (definitionTree corpus.definitionBase)))
  it "covers the corpus" (length corpus.cases `shouldSatisfy` (> 1500))
  forM_ (zip [0 :: Int ..] corpus.cases) $ \(index, c) -> do
    let op = text (field "op" c)
        label = show index <> " " <> T.unpack op <> " " <> take 120 (show (lookupMember "edits" c))
    case op of
      "construct" -> it label (construct (text (field "model" c)) (field "args" c) `shouldBe` outcome c)
      "definition" -> do
        let tree = definitionTree (edited corpus.definitionBase c)
        it (label <> " (compile)") (refusalOf (compileNetDefinition tree) `shouldBe` outcome (field "compile" c))
        it (label <> " (serialize)") (digestOf (serializeNetDefinition tree) `shouldBe` outcome (field "serialize" c))
      "serialize-document" ->
        it label (digestOf (serializeNetDocument (documentTree (edited corpus.documentBase c))) `shouldBe` outcome c)
      "project-document" ->
        it label (project net (edited corpus.projectionBase c) `shouldBe` outcome c)
      "parse-document" -> do
        let payload = wirePayload (edited corpus.documentBase c)
            parsed = parseNetDocument payload
        it (label <> " (parse)") (refusalOf parsed `shouldBe` outcome (field "parse" c))
        forM_ (lookupMember "serialize" c) $ \expected ->
          it (label <> " (serialize)") (either (const []) (pure . digestOf . serializeNetDocument) parsed `shouldBe` [outcome expected])
      other -> it label (expectationFailure ("unknown op " <> T.unpack other))

-- ---------------------------------------------------------------------------
-- Operations

refusalOf :: Either Text a -> Outcome
refusalOf = either Refused (const Ok)

digestOf :: Either Text ByteString -> Outcome
digestOf = either Refused (Digest . sha256Hex)

outcome :: Json -> Outcome
outcome c = case (lookupMember "error" c, lookupMember "sha256" c) of
  (Just (String e), _) -> Refused e
  (_, Just (String d)) -> Digest d
  _ -> Ok

-- | The validating constructor, given the reference's keyword arguments.
-- On success the result must be the record the arguments spell.
construct :: Text -> Json -> Outcome
construct model args = case model of
  "SymbolExpression" -> check (mkSymbolExpression (str "name")) (SymbolExpression (str "name"))
  "CelExpression" -> check (mkCelExpression (str "expression")) (CelExpression (str "expression"))
  "SymbolBehavior" -> check (mkSymbolBehavior (str "name") (str "uri")) (SymbolBehavior (str "name") (str "uri"))
  "CelBehavior" -> check (mkCelBehavior (str "expression") (str "uri")) (CelBehavior (str "expression") (str "uri"))
  "DelayDefinition" -> check (mkDelayDefinition (int "duration")) (DelayDefinition (int "duration"))
  "UntilDefinition" -> check (mkUntilDefinition (int "instant")) (UntilDefinition (int "instant"))
  "PlaceDefinition" -> check (mkPlaceDefinition (str "path") (optStr "color")) (placeTree args)
  "TransitionDefinition" ->
    let t = transitionTree args
     in check (mkTransitionDefinition t.path t.handler t.guards t.timers) t
  "ArcDefinition" ->
    let a = arcTree args
     in check (mkArcDefinition a.position a.source a.target a.mode a.weight a.color a.filter) a
  "NetDefinitionBody" ->
    let b = bodyTree args
     in check (mkNetDefinitionBody b.name b.places b.transitions b.arcs b.completion) b
  "NodePosition" -> let n = nodeTree args in check (mkNodePosition n.node n.x n.y) n
  "PortableViewV1" -> let v = viewTree args in check (mkPortableViewV1 v.nodes) v
  "MarkingToken" -> let t = tokenTree args in check (mkMarkingToken t.color t.payload) t
  "PlaceMarking" -> let m = markingTree args in check (mkPlaceMarking m.place m.tokens) m
  "LineageEntry" -> let e = entryTree args in check (mkLineageEntry e.id e.parent e.provenance e.marking e.metadata) e
  "ExecutionLineage" -> let l = lineageTree args in check (mkExecutionLineage l.head l.entries) l
  other -> Refused ("unknown model " <> other)
  where
    str key = text (field key args)
    int key = integer (field key args)
    optStr key = optional text (field key args)
    check :: (Eq a) => Either Text a -> a -> Outcome
    check built expected = case built of
      Left e -> Refused e
      Right value
        | value == expected -> Ok
        | otherwise -> Refused "constructed a different record"

-- | @project_net_document(net, positions, lineage=...)@: positions are a
-- mapping, so a node named twice keeps its last position.
project :: Net -> Json -> Outcome
project net tree = refusalOf (projectNetDocument net positions (optional lineageTree (field "lineage" tree)))
  where
    positions = case field "view" tree of
      Null -> Nothing
      v -> Just (dedupe [(n.node, (n.x, n.y)) | n <- (viewTree v).nodes])
    dedupe = \case
      [] -> []
      (k, v) : rest -> (k, lastFor k v rest) : dedupe (filter ((/= k) . fst) rest)
    lastFor k v rest = case [v' | (k', v') <- rest, k' == k] of
      [] -> v
      vs -> last vs

-- | The payload the reference parses: the document tree with its constants
-- and every tagged value resolved.
wirePayload :: Json -> ByteString
wirePayload tree = either (error . show) id (dumps defaultDumps document)
  where
    document =
      Object
        [ ("format", String "petrus-net-document")
        , ("version", Int 1)
        , ("definition", field "definition" tree)
        , ("view", Object (("version", Int 1) : members (field "view" tree)))
        , ("lineage", resolveLineage (field "lineage" tree))
        ]
    resolveLineage l =
      Object
        [ ("head", field "head" l)
        , ("entries", Array (map resolveEntry (array (field "entries" l))))
        ]
    resolveEntry e =
      Object
        [ ("id", field "id" e)
        , ("parent", field "parent" e)
        , ("provenance", field "provenance" e)
        , ("marking", Array (map resolveMarking (array (field "marking" e))))
        , ("metadata", Object [(k, tagged v) | (k, v) <- members (field "metadata" e)])
        ]
    resolveMarking m =
      Object
        [ ("place", field "place" m)
        , ("tokens", Array [Object [("color", field "color" t), ("data", tagged (field "data" t))] | t <- array (field "tokens" m)])
        ]

-- ---------------------------------------------------------------------------
-- Building records without validation (@model_construct@)

definitionTree :: Json -> NetDefinitionV3
definitionTree = NetDefinitionV3 . bodyTree . field "definition"

bodyTree :: Json -> NetDefinitionBody
bodyTree b =
  NetDefinitionBody
    (optional text (field "name" b))
    IntegerTimeDomain
    (map placeTree (array (field "places" b)))
    (map transitionTree (array (field "transitions" b)))
    (map arcTree (array (field "arcs" b)))
    (optional pureTree (field "completion" b))

placeTree :: Json -> PlaceDefinition
placeTree p = PlaceDefinition (text (field "path" p)) (optional text (field "color" p))

transitionTree :: Json -> TransitionDefinition
transitionTree t =
  TransitionDefinition
    (text (field "path" t))
    (optional handlerTree (field "handler" t))
    (map guardTree (array (field "guards" t)))
    (map timerTree (array (field "timers" t)))
  where
    handlerTree h = case text (field "kind" h) of
      "symbol" -> SymbolHandler (symbolTree h)
      _ -> AnonymousHandler (AnonymousBehavior (text (field "uri" h)))
    guardTree g = case text (field "kind" g) of
      "symbol" -> SymbolGuard (symbolTree g)
      "cel" -> CelGuard (CelBehavior (text (field "expression" g)) (text (field "uri" g)))
      _ -> AnonymousGuard (AnonymousBehavior (text (field "uri" g)))
    symbolTree s = SymbolBehavior (text (field "name" s)) (text (field "uri" s))
    timerTree timer = case text (field "kind" timer) of
      "delay" -> DelayDefinition (integer (field "duration" timer))
      _ -> UntilDefinition (integer (field "instant" timer))

arcTree :: Json -> ArcDefinition
arcTree a =
  ArcDefinition
    (integer (field "position" a))
    (text (field "source" a))
    (text (field "target" a))
    (mode (text (field "mode" a)))
    (integer (field "weight" a))
    (optional text (field "color" a))
    (optional pureTree (field "filter" a))
  where
    mode = \case
      "read" -> Read
      "inhibit" -> Inhibit
      _ -> Consume

pureTree :: Json -> PureExpression
pureTree e = case text (field "kind" e) of
  "symbol" -> SymbolExpression (text (field "name" e))
  _ -> CelExpression (text (field "expression" e))

documentTree :: Json -> NetDocumentV1
documentTree d =
  NetDocumentV1
    (definitionTree (field "definition" d))
    (optional viewTree (field "view" d))
    (optional lineageTree (field "lineage" d))

viewTree :: Json -> PortableViewV1
viewTree v = PortableViewV1 (map nodeTree (array (field "nodes" v)))

nodeTree :: Json -> NodePosition
nodeTree n = NodePosition (text (field "node" n)) (number (field "x" n)) (number (field "y" n))
  where
    number value = case tagged value of
      Int i -> IntNumber i
      Float d -> FloatNumber d
      other -> error ("not a coordinate: " <> show other)

lineageTree :: Json -> ExecutionLineage
lineageTree l = ExecutionLineage (integer (field "head" l)) (map entryTree (array (field "entries" l)))

entryTree :: Json -> LineageEntry
entryTree e =
  LineageEntry
    (integer (field "id" e))
    (optional integer (field "parent" e))
    (provenance (text (field "provenance" e)))
    (map markingTree (array (field "marking" e)))
    [(k, tagged v) | (k, v) <- members (field "metadata" e)]
  where
    provenance = \case
      "observed" -> Observed
      "simulated" -> Simulated
      _ -> Manual

markingTree :: Json -> PlaceMarking
markingTree m = PlaceMarking (text (field "place" m)) (map tokenTree (array (field "tokens" m)))

tokenTree :: Json -> MarkingToken
tokenTree t = MarkingToken (optional text (field "color" t)) (tagged (field "data" t))

-- | A tagged JSON value: @{"$float": ...}@ is a non-finite float,
-- @{"$nest": [n, kind, leaf]}@ wraps @leaf@ in @n@ one-element lists or
-- @{"k": ...}@ objects, and @{"$object": [[key, value], ...]}@ is an object.
tagged :: Json -> Json
tagged = \case
  Object [("$float", String spelled)] -> Float $ case spelled of
    "nan" -> 0 / 0
    "-inf" -> -1 / 0
    _ -> 1 / 0
  Object [("$object", Array pairs)] -> Object [(text k, tagged v) | Array [k, v] <- pairs]
  Object [("$nest", Array [Int depth, String kind, leaf])] ->
    iterate (if kind == "list" then Array . pure else Object . pure . ("k",)) (tagged leaf) !! fromInteger depth
  Object ms -> Object [(k, tagged v) | (k, v) <- ms]
  Array items -> Array (map tagged items)
  other -> other

-- ---------------------------------------------------------------------------
-- Loading

loadCorpus :: ByteString -> Either String Corpus
loadCorpus raw = do
  corpus <- parseJson pythonLoads raw
  let get key = maybe (Left ("corpus lacks " <> T.unpack key)) Right (lookupMember key corpus)
  definitionBase <- get "definition"
  documentBase <- get "document"
  projectionBase <- get "projection"
  cases <- array <$> get "cases"
  Right Corpus {definitionBase, documentBase, projectionBase, cases}

-- | The case's base with its @[path, value]@ edits applied in order.
edited :: Json -> Json -> Json
edited base c = foldl apply base (maybe [] array (lookupMember "edits" c))
  where
    apply tree = \case
      Array [Array path, value] -> setAt path value tree
      other -> error ("bad edit " <> show other)
    setAt path value tree = case path of
      [] -> value
      String key : rest -> case tree of
        Object ms
          | any ((== key) . fst) ms -> Object [(k, if k == key then setAt rest value v else v) | (k, v) <- ms]
          | otherwise -> Object (ms <> [(key, setAt rest value Null)])
        _ -> error ("not an object at " <> T.unpack key)
      Int index : rest -> case tree of
        Array items -> Array [if i == index then setAt rest value v else v | (i, v) <- zip [0 ..] items]
        _ -> error "not an array"
      other -> error ("bad path " <> show other)

field :: Text -> Json -> Json
field key value = maybe (error ("missing " <> T.unpack key <> " in " <> take 200 (show value))) id (lookupMember key value)

members :: Json -> [(Text, Json)]
members = \case
  Object ms -> ms
  other -> error ("not an object: " <> take 200 (show other))

array :: Json -> [Json]
array = \case
  Array items -> items
  other -> error ("not an array: " <> take 200 (show other))

text :: Json -> Text
text = \case
  String t -> t
  other -> error ("not a string: " <> take 200 (show other))

integer :: Json -> Integer
integer = \case
  Int i -> i
  other -> error ("not an integer: " <> take 200 (show other))

optional :: (Json -> a) -> Json -> Maybe a
optional f = \case
  Null -> Nothing
  value -> Just (f value)

sha256Hex :: ByteString -> Text
sha256Hex = T.pack . concatMap byte . BS.unpack . SHA256.hash
  where
    byte w = let h = showHex w "" in if length h == 1 then '0' : h else h
